echo "update 'slang'..."
rm -rf "build"
rm -rf "../../../../../AE-Bin/external/linux-e2k/slang"
rm -rf "temp"
mkdir "build"
git clone --recurse-submodules --branch "vulkan-sdk-1.4.309.0" "../../../../../3party/slang" "temp"
cp "temp/CMakeLists.txt" "temp/origin_CMakeLists.txt"
cp "slang_CMakeLists.txt" "temp/CMakeLists.txt"
cmake -S temp -B build -G "Unix Makefiles" -DAE_ENABLE_COMPILER_WARNINGS=OFF -DCMAKE_BUILD_TYPE=Debug -DCMAKE_INSTALL_PREFIX="../../../../../AE-Bin/external/linux-e2k/slang" 
cmake --build build --config Debug --target "slang" -j 6
cmake -S temp -B build -G "Unix Makefiles" -DAE_ENABLE_COMPILER_WARNINGS=OFF -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="../../../../../AE-Bin/external/linux-e2k/slang" 
cmake --build build --config Release --target "slang" -j 6
mkdir "../../../../../AE-Bin/external/linux-e2k/slang"
mkdir "../../../../../AE-Bin/external/linux-e2k/slang/include"
mkdir "../../../../../AE-Bin/external/linux-e2k/slang/lib"
cp "temp/LICENSE" "../../../../../AE-Bin/external/linux-e2k/slang/slang-LICENSE.txt"
cp "temp/include/slang.h" "../../../../../AE-Bin/external/linux-e2k/slang/include/slang.h"
cp "temp/include/slang-deprecated.h" "../../../../../AE-Bin/external/linux-e2k/slang/include/slang-deprecated.h"
cp "temp/include/slang-image-format-defs.h" "../../../../../AE-Bin/external/linux-e2k/slang/include/slang-image-format-defs.h"
cp "temp/include/slang-com-ptr.h" "../../../../../AE-Bin/external/linux-e2k/slang/include/slang-com-ptr.h"
cp "temp/include/slang-com-helper.h" "../../../../../AE-Bin/external/linux-e2k/slang/include/slang-com-helper.h"
rm -rf "temp"
rm -rf "build"
read -p "press any key..."
